import{_ as a,o as t,c as o,ae as i}from"./chunks/framework.B2ul6ABY.js";const h=JSON.parse('{"title":"Full Codebase Review and Remediation Plan","description":"","frontmatter":{},"headers":[],"relativePath":"historical/2026-05-remediation-dossiers/full-codebase-review-remediation-plan.md","filePath":"historical/2026-05-remediation-dossiers/full-codebase-review-remediation-plan.md"}'),r={name:"historical/2026-05-remediation-dossiers/full-codebase-review-remediation-plan.md"};function n(s,e,l,d,c,u){return t(),o("div",null,[...e[0]||(e[0]=[i('<blockquote><p><strong>Historical/Audit Artifact — Not Current Operator Instructions</strong><br> This page records an audit or remediation artifact from an earlier stage. It is not authoritative for current Saivage v3 behavior unless a current active doc explicitly revalidates it against current source and tests.</p></blockquote><h1 id="full-codebase-review-and-remediation-plan" tabindex="-1">Full Codebase Review and Remediation Plan <a class="header-anchor" href="#full-codebase-review-and-remediation-plan" aria-label="Permalink to &quot;Full Codebase Review and Remediation Plan&quot;">​</a></h1><p>Date: 2026-05-13 Scope: Saivage v3 source, tests, authored documentation, generated docs behavior, and live the target project deployment smoke checks.</p><h2 id="review-summary" tabindex="-1">Review Summary <a class="header-anchor" href="#review-summary" aria-label="Permalink to &quot;Review Summary&quot;">​</a></h2><p>This review focused on actionable defects and consistency risks rather than broad style preferences. The codebase has a solid typed foundation, broad tests, and the recent goal-level planner/executor/reviewer architecture is now mostly reflected in runtime code. The remaining issues found in this pass are concentrated in security boundaries, project-root isolation, and stale operator/agent-facing text.</p><h2 id="findings" tabindex="-1">Findings <a class="header-anchor" href="#findings" aria-label="Permalink to &quot;Findings&quot;">​</a></h2><h3 id="_1-agent-file-reads-lack-project-root-containment" tabindex="-1">1. Agent file reads lack project-root containment <a class="header-anchor" href="#_1-agent-file-reads-lack-project-root-containment" aria-label="Permalink to &quot;1. Agent file reads lack project-root containment&quot;">​</a></h3><p><code>readProjectFileAtomic(projectRoot, relativePath)</code> strips a leading <code>./</code>, checks sensitive-file names, and then joins the requested path to <code>projectRoot</code>. It does not reject absolute paths or <code>..</code> escapes before reading. This function is documented as the main file-read integration point for agents, so it must enforce containment even if current call sites are limited.</p><p>Impact: A future or existing agent tool using this helper could read outside the managed project root.</p><p>Plan: Resolve <code>projectRoot</code> and requested paths, reject absolute requested paths, reject paths whose normalized relative path escapes the root, and add regression tests.</p><h3 id="_2-analyst-tool-schemas-still-advertise-removed-plan-card-type" tabindex="-1">2. Analyst tool schemas still advertise removed <code>plan</code> card type <a class="header-anchor" href="#_2-analyst-tool-schemas-still-advertise-removed-plan-card-type" aria-label="Permalink to &quot;2. Analyst tool schemas still advertise removed `plan` card type&quot;">​</a></h3><p><code>ANALYST_TOOL_DEFINITIONS</code> still describes <code>plan</code> as a non-terminal card type and as a valid filter value. The runtime/card store now rejects plan-card creation and stores planning state on goals.</p><p>Impact: The analyst LLM may request invalid tool calls, causing avoidable API/tool failures and confusing users.</p><p>Plan: Update the tool schema text and add tests that the advertised card types do not include <code>plan</code>.</p><h3 id="_3-analyst-handlers-are-global-singletons-not-scoped-by-project-root" tabindex="-1">3. Analyst handlers are global singletons not scoped by project root <a class="header-anchor" href="#_3-analyst-handlers-are-global-singletons-not-scoped-by-project-root" aria-label="Permalink to &quot;3. Analyst handlers are global singletons not scoped by project root&quot;">​</a></h3><p>The HTTP chat routes and WebSocket handler each lazily create a module-level <code>AnalystHandler</code>. If the same Node process creates servers for different project roots, the later server can reuse a handler bound to the earlier root.</p><p>Impact: Tests, embedded deployments, or future multi-project operation can leak state/actions across project roots.</p><p>Plan: Replace singletons with per-project-root handler maps in both modules.</p><h3 id="_4-authored-docs-contain-stale-or-broken-operator-facing-references" tabindex="-1">4. Authored docs contain stale or broken operator-facing references <a class="header-anchor" href="#_4-authored-docs-contain-stale-or-broken-operator-facing-references" aria-label="Permalink to &quot;4. Authored docs contain stale or broken operator-facing references&quot;">​</a></h3><p><code>docs/index.md</code> still describes the old <code>Planner -&gt; Manager -&gt; Workers</code> architecture in the introduction even though its architecture section is correct. <code>README.md</code> links to uppercase documentation filenames that do not exist on this Linux filesystem.</p><p>Impact: New operators and agents reading docs receive contradictory architecture guidance or broken links.</p><p>Plan: Update the intro to planner/executor/reviewer and fix README links to existing lowercase docs files.</p><h3 id="_5-generated-docs-output-is-noisy-in-git-status" tabindex="-1">5. Generated docs output is noisy in git status <a class="header-anchor" href="#_5-generated-docs-output-is-noisy-in-git-status" aria-label="Permalink to &quot;5. Generated docs output is noisy in git status&quot;">​</a></h3><p><code>docs/.vitepress/dist</code> has many changed/deleted hashed assets from builds. This is generated output, so it should be regenerated by the validation step rather than hand-edited.</p><p>Impact: Review noise and possible stale served docs if build artifacts are not refreshed after authored docs change.</p><p>Plan: Run <code>npm run docs:verify</code> or root build after fixes; do not manually patch generated dist files.</p><h2 id="execution-stages" tabindex="-1">Execution Stages <a class="header-anchor" href="#execution-stages" aria-label="Permalink to &quot;Execution Stages&quot;">​</a></h2><h3 id="stage-1-security-and-isolation-fixes" tabindex="-1">Stage 1: Security and Isolation Fixes <a class="header-anchor" href="#stage-1-security-and-isolation-fixes" aria-label="Permalink to &quot;Stage 1: Security and Isolation Fixes&quot;">​</a></h3><ul><li>Harden <code>readProjectFileAtomic</code> with containment checks.</li><li>Add regression coverage for <code>..</code> traversal and absolute path rejection.</li><li>Scope analyst handlers per project root for HTTP chat and WebSocket paths.</li></ul><p>Acceptance criteria:</p><ul><li>Agent file reads cannot escape project root.</li><li>Multiple project roots in one process receive distinct analyst handlers.</li><li>Existing chat behavior remains unchanged for a single project.</li></ul><h3 id="stage-2-prompt-tool-contract-cleanup" tabindex="-1">Stage 2: Prompt/Tool Contract Cleanup <a class="header-anchor" href="#stage-2-prompt-tool-contract-cleanup" aria-label="Permalink to &quot;Stage 2: Prompt/Tool Contract Cleanup&quot;">​</a></h3><ul><li>Remove <code>plan</code> from analyst tool card-type descriptions.</li><li>Add a regression test that tool definitions no longer advertise <code>plan</code> as a creatable/filterable type.</li><li>Update stale fake-agent planner wording.</li></ul><p>Acceptance criteria:</p><ul><li>Analyst tool definitions align with the card schema and runtime contract.</li><li>Tests fail if <code>plan</code> is reintroduced into analyst tool type guidance.</li></ul><h3 id="stage-3-documentation-consistency" tabindex="-1">Stage 3: Documentation Consistency <a class="header-anchor" href="#stage-3-documentation-consistency" aria-label="Permalink to &quot;Stage 3: Documentation Consistency&quot;">​</a></h3><ul><li>Fix stale architecture wording in authored docs.</li><li>Fix README documentation links to the real lowercase files.</li><li>Ensure the new review plan is discoverable from docs index or README.</li></ul><p>Acceptance criteria:</p><ul><li>Authored docs no longer present the old Manager/Workers architecture as current.</li><li>README links resolve on Linux.</li><li>The remediation plan document remains in the repo for auditability.</li></ul><h3 id="stage-4-validation-and-live-verification" tabindex="-1">Stage 4: Validation and Live Verification <a class="header-anchor" href="#stage-4-validation-and-live-verification" aria-label="Permalink to &quot;Stage 4: Validation and Live Verification&quot;">​</a></h3><ul><li>Run focused tests for touched areas.</li><li>Run full typecheck and build.</li><li>Run Vue SFC duplicate-block guard before build.</li><li>Restart the LXC service for the target project.</li><li>Verify <code>/health</code>, authenticated <code>/api/state</code>, browser pages, and console health.</li></ul><p>Acceptance criteria:</p><ul><li>All selected tests and build commands pass.</li><li>Live service restarts successfully and reports healthy runtime state.</li><li>Browser smoke checks show the control room loading without fresh console errors.</li></ul><h2 id="replan-rule" tabindex="-1">Replan Rule <a class="header-anchor" href="#replan-rule" aria-label="Permalink to &quot;Replan Rule&quot;">​</a></h2><p>If validation exposes new failures, append a short update to this document or create a follow-up remediation note, then repeat implementation and validation until the failing issues are resolved or clearly classified as unrelated pre-existing worktree state.</p><h2 id="replan-update-backend-validation-failures" tabindex="-1">Replan Update: Backend Validation Failures <a class="header-anchor" href="#replan-update-backend-validation-failures" aria-label="Permalink to &quot;Replan Update: Backend Validation Failures&quot;">​</a></h2><p>The first full backend validation pass exposed additional stale contracts and one runtime trigger bug:</p><ul><li>Schema fixtures still contained <code>card-plan.json</code> and diary/review records using <code>plan_card_id</code> even though goal-level planning now requires valid card types and <code>goal_card_id</code>.</li><li>Card-store regression tests accidentally asserted that <code>research</code> cards should be forbidden instead of exercising the removed <code>plan</code> type.</li><li>An OAuth profile test depended on <code>/work/saivage-v3</code> being present, which is only true in the container deployment and should not be required for host tests.</li><li>Continuous improvement checks only ran through backlog auto-dispatch, so <code>continuousImprovement: true</code> with <code>autoDispatchBacklog: false</code> never invoked project-level improvement.</li><li>A supervisor force-cancel integration test advanced fake timers across many periodic intervals while trying to test only the force-cancel timeout.</li></ul><p>Remediation applied:</p><ul><li>Replaced the stale plan-card fixture with an architecture-card fixture and updated diary/review fixtures to goal-level fields.</li><li>Restored explicit plan-card rejection messages in <code>CardStore</code> before schema validation.</li><li>Made the OAuth profile suite independent of container-only credential mounts.</li><li>Restored continuous-improvement startup checks when backlog auto-dispatch is disabled.</li><li>Adjusted the supervisor integration test interval so the force-cancel timer can be tested deterministically.</li></ul>',50)])])}const m=a(r,[["render",n]]);export{h as __pageData,m as default};
